// (עבר QA, TestFlight 1.0.0 (20) + OTA) — @known-bug снят 19.10. На «יש! יצרת חשבון» 5 точек 'progress-dot', активная (ширина 32)
// крайняя справа (Figma 444:818, RTL). Точки снимаются в RG-07 (та же регистрация), RG-07b только проверяет; без RG-07 — skip.
// Порядок экранов изменён #f688d2b0 (принят 19.10): «שלח» → сразу «יש! יצרת חשבון», «בואו נתקדם» → «תאריך לידה» (не главная);
// настройку до главной проходит человек. Полный порядок и точки по шагам — RG-09 / RG-07d (rg-09-onboarding-order-dots-location-f688d2b0.e2e.ts).
import { $$, driver, expect } from '@wdio/globals';
import { byText, byTextContains, tapText } from '../../helpers/ui.ts';
import { ensureAppReady, isLoggedIn, logout, login } from '../../helpers/app.ts';
import { skipWith, shown } from '../_lib/app-0710.ts';

const TITLE = 'יש! יצרת חשבון';
const POINTS = ['התאמה אוטומטית לפי מיקום וזמן', 'תזכורות חכמות לזמני תפילה', 'מעקב אחר התקדמות והרגלים'];
const SHOT = new URL('../../runs/add32f72-account-created-icons.png', import.meta.url).pathname;

type Dot = { x: number; width: number; mark: string };
/** Точки прогресса на «יש! יצרת חשבון» (снимаются в RG-07, проверяются в RG-07b). null — RG-07 не дошёл до экрана. */
let dots: Dot[] | null = null;

async function readProgressDots(): Promise<Dot[]> {
  const els = driver.isAndroid
    ? await $$('android=new UiSelector().description("progress-dot")').getElements()
    : await $$('-ios predicate string:name == "progress-dot" OR label == "progress-dot"').getElements();
  const out: Dot[] = [];
  for (const el of els) {
    const { x } = await el.getLocation();
    const { width } = (await el.getSize()) as { width: number; height: number };
    const mark = driver.isAndroid
      ? String(await el.getAttribute('selected').catch(() => ''))
      : `${await el.getAttribute('value').catch(() => '')}|${await el.getAttribute('selected').catch(() => '')}`;
    out.push({ x, width, mark });
  }
  return out.sort((a, b) => a.x - b.x);
}

/** Индекс активной точки слева направо: уникальная по ширине (самая широкая) или по атрибуту; -1 — не определить. */
function activeIndex(d: Dot[]): number {
  if (d.length < 2) return -1;
  const maxW = Math.max(...d.map((p) => p.width));
  const wide = d.filter((p) => p.width === maxW);
  if (wide.length === 1 && maxW - Math.min(...d.map((p) => p.width)) >= 2) return d.indexOf(wide[0]);
  const odd = d.filter((p) => d.filter((q) => q.mark === p.mark).length === 1);
  if (odd.length === 1) return d.indexOf(odd[0]);
  return -1;
}

describe('Регистрация: иконки «יש! יצרת חשבון»', () => {
  it('RG-07 Новая регистрация (человек) → «שלח» → «יש! יצרת חשבון»: 3 пункта (антенна/будильник/глаз), «בואו נתקדם» → «תאריך לידה»; скрин иконок для сверки с Figma 444:818 #add32f72 @data @manual-check', async function () {
    if (process.env.QA_REG_MANUAL !== '1') skipWith(this, 'регистрация нового номера с OTP — вручную; запуск с QA_REG_MANUAL=1 и человеком у телефона');
    this.timeout(1200000);
    try {
      if (await isLoggedIn()) await logout();
      console.log('[RG-07] @manual-check: зарегистрируйте НОВЫЙ аккаунт: «יצירת חשבון» → «שלח» (после этого сразу «יש! יצרת חשבון», #f688d2b0). Тест ждёт до 15 минут…');
      await driver.waitUntil(async () => (await shown(byText(TITLE))) || (await shown(byText('תאריך לידה'))),
        { timeout: 900000, interval: 3000, timeoutMsg: 'не дождались «יש! יצרת חשבון» после «שלח»' });

      await expect(byText(TITLE)).toBeDisplayed({ wait: 20000 });
      for (const p of POINTS) await expect(byTextContains(p)).toBeDisplayed();
      await expect(byText('בואו נתקדם')).toBeDisplayed();

      await driver.saveScreenshot(SHOT);
      try { dots = await readProgressDots(); console.log('[RG-07] точки прогресса (для RG-07b, #ba6e9b8d):', JSON.stringify(dots)); }
      catch (e) { console.warn('[RG-07] точки прогресса не прочитаны', e); }
      console.log(`[RG-07] @manual-check: сверить ${SHOT} с Figma 444:818 и .qa/screenshots/add32f72-ios-b20-vs-figma-444-818.png — антенна: волны справа сверху наружу; будильник: дуги наружу; глаз без изменений.`);

      // #f688d2b0: «בואו נתקדם» → «תאריך לידה»; дальше настройку проходит человек до главной.
      await tapText('בואו נתקדם');
      await expect(byText('תאריך לידה')).toBeDisplayed({ wait: 30000 });
      console.log('[RG-07] @manual-check: пройдите настройку до главной («מוכנים להתחיל!» → «בוא נתחיל»), не через «חזרה». Тест ждёт до 15 минут…');
      await driver.waitUntil(isLoggedIn, { timeout: 900000, interval: 3000, timeoutMsg: 'настройка не доведена до главной' });
    } finally {
      try { if (await isLoggedIn()) await logout(); await login('USER1'); } catch (e) { console.warn('[RG-07] вернуть USER1 вручную', e); await ensureAppReady().catch(() => {}); }
    }
  });

  it('RG-07b «יש! יצרת חשבון»: 5 точек прогресса (progress-dot), активная — крайняя справа (Figma 444:818) #ba6e9b8d @data @manual-check', function () {
    if (process.env.QA_REG_MANUAL !== '1') skipWith(this, 'точки снимаются в RG-07 (регистрация вручную); запуск с QA_REG_MANUAL=1');
    if (!dots) skipWith(this, 'RG-07 не дошёл до «יש! יצרת חשבון» — точки не сняты');
    const active = activeIndex(dots);
    if (active < 0) console.log(`[RG-07b] @manual-check: активная точка не определилась по ширине/атрибутам — сверить ${SHOT} с Figma 444:818 (активная справа)`);
    expect({ count: dots.length, activeIsRightmost: active < 0 ? 'manual' : active === dots.length - 1 })
      .toEqual({ count: 5, activeIsRightmost: active < 0 ? 'manual' : true });
  });
});
